def pending_review_to_assignment_statuses(apps, schema_editor):
    """Existing "Pending Review" requests become Assigned (if they already
    have assignees) or Unassigned. Every other status is unchanged and
    existing assignments are untouched."""
    SupportRequest = apps.get_model("communications", "SupportRequest")
    for sr in SupportRequest.objects.filter(status="pending_review"):
        sr.status = "assigned" if sr.assigned_to.exists() else "unassigned"
        sr.save(update_fields=["status"])


def assignment_statuses_to_pending_review(apps, schema_editor):
    SupportRequest = apps.get_model("communications", "SupportRequest")
    SupportRequest.objects.filter(status__in=["unassigned", "assigned"]).update(status="pending_review")
    SupportRequest.objects.filter(status__in=["needs_clarification", "clarification_provided", "on_hold"]).update(
        status="in_progress"
    )


